'use client';

import * as React from 'react';
import { Button } from '@/components/slipstream/button';
import { cn } from '@/lib/utils';

export type ConfirmationStatus = 'pending' | 'approved' | 'rejected';

export interface ConfirmationProps {
  /** Human-readable summary of the action requiring approval. */
  title: string;
  /** Optional detail: affected resource, arguments preview, risk note. */
  description?: string;
  /** Tool or action name shown as a mono chip. */
  toolName?: string;
  /** Controlled outcome; omit for fully interactive uncontrolled use. */
  status?: ConfirmationStatus;
  onApprove?: () => void;
  onReject?: () => void;
  labels?: {
    approve?: string;
    reject?: string;
    approved?: string;
    rejected?: string;
  };
  className?: string;
}

const statusChipClasses: Record<ConfirmationStatus, string> = {
  pending: 'bg-warning/10 text-warning border-warning/20',
  approved: 'bg-success/10 text-success border-success/20',
  rejected: 'bg-destructive/10 text-destructive border-destructive/20',
};

/**
 * Human-in-the-loop approval gate for agent actions (tool execution,
 * destructive operations). The agent pauses until the user decides.
 */
const Confirmation = React.forwardRef<HTMLDivElement, ConfirmationProps>(
  (
    {
      title,
      description,
      toolName,
      status: controlledStatus,
      onApprove,
      onReject,
      labels,
      className,
      ...props
    },
    ref
  ) => {
    const [internalStatus, setInternalStatus] = React.useState<ConfirmationStatus>('pending');
    const status = controlledStatus ?? internalStatus;

    const t = {
      approve: labels?.approve ?? 'Approve',
      reject: labels?.reject ?? 'Reject',
      approved: labels?.approved ?? 'Approved',
      rejected: labels?.rejected ?? 'Rejected',
    };

    const decide = (next: Exclude<ConfirmationStatus, 'pending'>) => {
      setInternalStatus(next);
      (next === 'approved' ? onApprove : onReject)?.();
    };

    return (
      <div
        ref={ref}
        role={status === 'pending' ? 'alertdialog' : undefined}
        aria-label={status === 'pending' ? title : undefined}
        className={cn(
          'rounded-lg border p-4 bg-muted/30 max-w-md',
          status === 'pending' && 'border-warning/40',
          className
        )}
        {...props}
      >
        <div className="flex items-center justify-between gap-2 mb-2">
          <div className="text-sm font-medium text-foreground">{title}</div>
          <span
            className={cn(
              'text-xs px-2 py-0.5 rounded-full border whitespace-nowrap',
              statusChipClasses[status]
            )}
          >
            {status === 'approved' ? t.approved : status === 'rejected' ? t.rejected : 'Pending'}
          </span>
        </div>

        {description && (
          <div className="text-sm text-muted-foreground mb-1">{description}</div>
        )}
        {toolName && (
          <div className="text-xs font-mono text-muted-foreground mb-3">{toolName}</div>
        )}

        {status === 'pending' && (
          <div className="flex gap-2 mt-2">
            <Button size="sm" onClick={() => decide('approved')}>
              {t.approve}
            </Button>
            <Button size="sm" variant="outline" onClick={() => decide('rejected')}>
              {t.reject}
            </Button>
          </div>
        )}
      </div>
    );
  }
);
Confirmation.displayName = 'Confirmation';

export { Confirmation };

{
  "id": "confirmation",
  "name": "Confirmation",
  "tier": "molecule",
  "description": "Human-in-the-loop approval gate for agent actions. Pauses execution until the user approves or rejects.",
  "designIntent": "Make destructive or consequential tool calls require explicit user consent.",
  "props": [
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Summary of the action requiring approval."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Detail: affected resource or risk note."
    },
    {
      "name": "toolName",
      "type": "string",
      "required": false,
      "description": "Tool/action name shown as mono text."
    },
    {
      "name": "status",
      "type": "'pending' | 'approved' | 'rejected'",
      "defaultValue": "pending",
      "required": false,
      "description": "Controlled outcome; omit for uncontrolled."
    },
    {
      "name": "onApprove",
      "type": "() => void",
      "required": false,
      "description": "Called on approval."
    },
    {
      "name": "onReject",
      "type": "() => void",
      "required": false,
      "description": "Called on rejection."
    },
    {
      "name": "labels",
      "type": "object",
      "required": false,
      "description": "Overrides for approve/reject/approved/rejected labels."
    }
  ],
  "examples": [
    {
      "title": "Gate a destructive tool",
      "code": "<Confirmation title=\"Delete all files?\" toolName=\"delete_all\" onApprove={run} onReject={cancel} />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Do not auto-approve after timeout",
      "explanation": "Silent approval defeats the safety purpose; keep waiting or fail explicitly."
    }
  ],
  "accessibility": [
    {
      "feature": "Dialog semantics",
      "implementation": "Pending state renders role=alertdialog labeled by the title."
    },
    {
      "feature": "Outcome announcement",
      "implementation": "Status chip text announces Approved/Rejected."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1"
}
